CREATE OR REPLACE FUNCTION public.phase6_can_finance(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(_uid, 'admin') OR public.has_permission(_uid, 'finance.view') OR public.has_permission(_uid, 'finance.edit'); $$;
CREATE OR REPLACE FUNCTION public.phase6_can_quality(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(_uid, 'admin') OR public.has_permission(_uid, 'quality.view') OR public.has_permission(_uid, 'quality.edit'); $$;

ALTER TABLE public.vendors ADD COLUMN IF NOT EXISTS vendor_code text, ADD COLUMN IF NOT EXISTS supplier_status text NOT NULL DEFAULT 'PENDING' CHECK (supplier_status IN ('PENDING','APPROVED','CONDITIONAL','BLOCKED')), ADD COLUMN IF NOT EXISTS quality_risk text NOT NULL DEFAULT 'STANDARD' CHECK (quality_risk IN ('LOW','STANDARD','HIGH','CRITICAL')), ADD COLUMN IF NOT EXISTS bank_details jsonb, ADD COLUMN IF NOT EXISTS customer_nominated boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS nomination_evidence text, ADD COLUMN IF NOT EXISTS approved_categories jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.purchase_orders ADD COLUMN IF NOT EXISTS project_id uuid REFERENCES public.projects(id), ADD COLUMN IF NOT EXISTS source_request_id uuid, ADD COLUMN IF NOT EXISTS original_delivery_date date, ADD COLUMN IF NOT EXISTS buyer_approval_status text NOT NULL DEFAULT 'NOT_REQUIRED' CHECK (buyer_approval_status IN ('NOT_REQUIRED','PENDING','APPROVED','REJECTED')), ADD COLUMN IF NOT EXISTS approved_by uuid, ADD COLUMN IF NOT EXISTS approved_at timestamptz;
UPDATE public.purchase_orders SET original_delivery_date = expected_delivery_date WHERE original_delivery_date IS NULL;
ALTER TABLE public.goods_receipt_notes ADD COLUMN IF NOT EXISTS quality_status text NOT NULL DEFAULT 'NOT_REQUIRED' CHECK (quality_status IN ('NOT_REQUIRED','PENDING_IQC','ACCEPTED','HOLD','REJECTED')), ADD COLUMN IF NOT EXISTS barcode_payload text;
ALTER TABLE public.goods_receipt_items ADD COLUMN IF NOT EXISTS date_code text, ADD COLUMN IF NOT EXISTS reel_id text, ADD COLUMN IF NOT EXISTS quality_status text NOT NULL DEFAULT 'AVAILABLE' CHECK (quality_status IN ('AVAILABLE','QUALITY_HOLD','REJECTED','BLOCKED'));

CREATE TABLE IF NOT EXISTS public.purchase_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_number text NOT NULL UNIQUE, source_type text NOT NULL DEFAULT 'MANUAL' CHECK (source_type IN ('MANUAL','PROJECT','BOM_SHORTAGE','PROTOTYPE_BUILD','R&D','TESTING','CERTIFICATION','MECHANICAL','QUALITY','PRODUCTION','FACILITY','HR','OTHER')), source_entity_id uuid, project_id uuid REFERENCES public.projects(id), bom_id uuid REFERENCES public.project_boms(id), department_id uuid REFERENCES public.departments(id), requester_id uuid NOT NULL DEFAULT auth.uid(), status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','SUBMITTED','UNDER_REVIEW','APPROVED','REJECTED','CONVERTED','CANCELLED')), urgency text NOT NULL DEFAULT 'NORMAL' CHECK (urgency IN ('LOW','NORMAL','HIGH','URGENT')), urgency_reason text, delay_impact text, required_date date, is_capex boolean NOT NULL DEFAULT false, notes text, submitted_at timestamptz, approved_by uuid, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.purchase_requests TO authenticated; GRANT ALL ON public.purchase_requests TO service_role; ALTER TABLE public.purchase_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "purchase_requests_read_internal" ON public.purchase_requests FOR SELECT TO authenticated USING (true); CREATE POLICY "purchase_requests_create_internal" ON public.purchase_requests FOR INSERT TO authenticated WITH CHECK (requester_id = auth.uid() OR public.can_purchase(auth.uid())); CREATE POLICY "purchase_requests_update_purchase" ON public.purchase_requests FOR UPDATE TO authenticated USING (requester_id = auth.uid() OR public.can_purchase(auth.uid())) WITH CHECK (requester_id = auth.uid() OR public.can_purchase(auth.uid())); CREATE POLICY "purchase_requests_delete_draft" ON public.purchase_requests FOR DELETE TO authenticated USING (requester_id = auth.uid() AND status = 'DRAFT');
CREATE TABLE IF NOT EXISTS public.purchase_request_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_request_id uuid NOT NULL REFERENCES public.purchase_requests(id) ON DELETE CASCADE, component_id uuid REFERENCES public.components(id), mpn text, description text, required_quantity numeric NOT NULL CHECK (required_quantity > 0), shortage_quantity numeric, unit text NOT NULL DEFAULT 'EA', target_unit_cost numeric, notes text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.purchase_request_items TO authenticated; GRANT ALL ON public.purchase_request_items TO service_role; ALTER TABLE public.purchase_request_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "purchase_request_items_read_internal" ON public.purchase_request_items FOR SELECT TO authenticated USING (true); CREATE POLICY "purchase_request_items_manage_request" ON public.purchase_request_items FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.purchase_requests r WHERE r.id = purchase_request_id AND (r.requester_id = auth.uid() OR public.can_purchase(auth.uid())))) WITH CHECK (EXISTS (SELECT 1 FROM public.purchase_requests r WHERE r.id = purchase_request_id AND (r.requester_id = auth.uid() OR public.can_purchase(auth.uid()))));
CREATE TABLE IF NOT EXISTS public.rfqs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rfq_number text NOT NULL UNIQUE, purchase_request_id uuid REFERENCES public.purchase_requests(id), project_id uuid REFERENCES public.projects(id), status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','SENT','CLOSED','CANCELLED')), response_due_date date, terms text, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.rfqs TO authenticated; GRANT ALL ON public.rfqs TO service_role; ALTER TABLE public.rfqs ENABLE ROW LEVEL SECURITY; CREATE POLICY "rfqs_read_internal" ON public.rfqs FOR SELECT TO authenticated USING (true); CREATE POLICY "rfqs_manage_purchase" ON public.rfqs FOR ALL TO authenticated USING (public.can_purchase(auth.uid())) WITH CHECK (public.can_purchase(auth.uid()));
CREATE TABLE IF NOT EXISTS public.rfq_vendors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rfq_id uuid NOT NULL REFERENCES public.rfqs(id) ON DELETE CASCADE, vendor_id uuid NOT NULL REFERENCES public.vendors(id), sent_at timestamptz, acknowledged_at timestamptz, status text NOT NULL DEFAULT 'INVITED' CHECK (status IN ('INVITED','SENT','ACKNOWLEDGED','DECLINED','RESPONDED')), UNIQUE(rfq_id, vendor_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.rfq_vendors TO authenticated; GRANT ALL ON public.rfq_vendors TO service_role; ALTER TABLE public.rfq_vendors ENABLE ROW LEVEL SECURITY; CREATE POLICY "rfq_vendors_read_internal" ON public.rfq_vendors FOR SELECT TO authenticated USING (true); CREATE POLICY "rfq_vendors_manage_purchase" ON public.rfq_vendors FOR ALL TO authenticated USING (public.can_purchase(auth.uid())) WITH CHECK (public.can_purchase(auth.uid()));
CREATE TABLE IF NOT EXISTS public.quotations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quotation_number text NOT NULL, rfq_id uuid REFERENCES public.rfqs(id), vendor_id uuid NOT NULL REFERENCES public.vendors(id), currency text NOT NULL DEFAULT 'INR', quoted_at date, valid_until date, lead_time_days integer, payment_terms text, status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','NEEDS_REVIEW','CONFIRMED','REJECTED','EXPIRED')), source_file_path text, extraction jsonb, extraction_confirmed_by uuid, extraction_confirmed_at timestamptz, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(vendor_id, quotation_number));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.quotations TO authenticated; GRANT ALL ON public.quotations TO service_role; ALTER TABLE public.quotations ENABLE ROW LEVEL SECURITY; CREATE POLICY "quotations_read_internal" ON public.quotations FOR SELECT TO authenticated USING (true); CREATE POLICY "quotations_manage_purchase" ON public.quotations FOR ALL TO authenticated USING (public.can_purchase(auth.uid())) WITH CHECK (public.can_purchase(auth.uid()));
CREATE TABLE IF NOT EXISTS public.quotation_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quotation_id uuid NOT NULL REFERENCES public.quotations(id) ON DELETE CASCADE, component_id uuid REFERENCES public.components(id), mpn text, description text, quantity numeric NOT NULL CHECK (quantity > 0), unit_price numeric NOT NULL CHECK (unit_price >= 0), moq numeric, lead_time_days integer, notes text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.quotation_items TO authenticated; GRANT ALL ON public.quotation_items TO service_role; ALTER TABLE public.quotation_items ENABLE ROW LEVEL SECURITY; CREATE POLICY "quotation_items_read_internal" ON public.quotation_items FOR SELECT TO authenticated USING (true); CREATE POLICY "quotation_items_manage_purchase" ON public.quotation_items FOR ALL TO authenticated USING (public.can_purchase(auth.uid())) WITH CHECK (public.can_purchase(auth.uid()));
CREATE TABLE IF NOT EXISTS public.po_delivery_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), po_id uuid NOT NULL REFERENCES public.purchase_orders(id), original_delivery_date date, proposed_delivery_date date NOT NULL, proposed_by_vendor boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'PROPOSED' CHECK (status IN ('PROPOSED','ACCEPTED','REJECTED','CLARIFICATION_REQUESTED')), reason text, evidence_path text, decided_by uuid, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.po_delivery_revisions TO authenticated; GRANT ALL ON public.po_delivery_revisions TO service_role; ALTER TABLE public.po_delivery_revisions ENABLE ROW LEVEL SECURITY; CREATE POLICY "po_delivery_revisions_read_internal" ON public.po_delivery_revisions FOR SELECT TO authenticated USING (true); CREATE POLICY "po_delivery_revisions_manage_purchase" ON public.po_delivery_revisions FOR ALL TO authenticated USING (public.can_purchase(auth.uid())) WITH CHECK (public.can_purchase(auth.uid()));
CREATE TABLE IF NOT EXISTS public.po_shipments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), po_id uuid NOT NULL REFERENCES public.purchase_orders(id), dispatch_date date, courier text, awb_number text, packing_list_path text, invoice_path text, expected_arrival_date date, tracking_provider text, tracking_payload jsonb, status text NOT NULL DEFAULT 'DISPATCHED' CHECK (status IN ('PLANNED','DISPATCHED','IN_TRANSIT','DELIVERED','EXCEPTION')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.po_shipments TO authenticated; GRANT ALL ON public.po_shipments TO service_role; ALTER TABLE public.po_shipments ENABLE ROW LEVEL SECURITY; CREATE POLICY "po_shipments_read_internal" ON public.po_shipments FOR SELECT TO authenticated USING (true); CREATE POLICY "po_shipments_manage_purchase" ON public.po_shipments FOR ALL TO authenticated USING (public.can_purchase(auth.uid())) WITH CHECK (public.can_purchase(auth.uid()));
CREATE TABLE IF NOT EXISTS public.inventory_lots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), component_id uuid NOT NULL REFERENCES public.components(id), grn_item_id uuid REFERENCES public.goods_receipt_items(id), location_id uuid REFERENCES public.locations(id), lot_number text, date_code text, reel_id text, quantity_received numeric NOT NULL DEFAULT 0, quantity_available numeric NOT NULL DEFAULT 0, quality_status text NOT NULL DEFAULT 'AVAILABLE' CHECK (quality_status IN ('AVAILABLE','QUALITY_HOLD','REJECTED','BLOCKED')), expiry_date date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.inventory_lots TO authenticated; GRANT ALL ON public.inventory_lots TO service_role; ALTER TABLE public.inventory_lots ENABLE ROW LEVEL SECURITY; CREATE POLICY "inventory_lots_read_internal" ON public.inventory_lots FOR SELECT TO authenticated USING (true); CREATE POLICY "inventory_lots_manage_stores" ON public.inventory_lots FOR ALL TO authenticated USING (public.can_inward(auth.uid())) WITH CHECK (public.can_inward(auth.uid()));
CREATE TABLE IF NOT EXISTS public.inventory_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), component_id uuid NOT NULL REFERENCES public.components(id), project_id uuid REFERENCES public.projects(id), lot_id uuid REFERENCES public.inventory_lots(id), quantity numeric NOT NULL CHECK (quantity > 0), status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','FULFILLED','RELEASED')), source_entity_id uuid, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.inventory_reservations TO authenticated; GRANT ALL ON public.inventory_reservations TO service_role; ALTER TABLE public.inventory_reservations ENABLE ROW LEVEL SECURITY; CREATE POLICY "inventory_reservations_read_internal" ON public.inventory_reservations FOR SELECT TO authenticated USING (true); CREATE POLICY "inventory_reservations_manage_internal" ON public.inventory_reservations FOR ALL TO authenticated USING (created_by = auth.uid() OR public.can_inward(auth.uid())) WITH CHECK (created_by = auth.uid() OR public.can_inward(auth.uid()));
CREATE TABLE IF NOT EXISTS public.incoming_inspections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), grn_id uuid NOT NULL REFERENCES public.goods_receipt_notes(id), grn_item_id uuid NOT NULL REFERENCES public.goods_receipt_items(id), vendor_id uuid REFERENCES public.vendors(id), status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','ACCEPTED','ACCEPTED_WITH_DEVIATION','HOLD','REJECTED','REINSPECTION_REQUIRED')), applicability_reason text, sampling_plan text, findings text, evidence_path text, disposition_by uuid, disposition_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(grn_item_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.incoming_inspections TO authenticated; GRANT ALL ON public.incoming_inspections TO service_role; ALTER TABLE public.incoming_inspections ENABLE ROW LEVEL SECURITY; CREATE POLICY "incoming_inspections_read_internal" ON public.incoming_inspections FOR SELECT TO authenticated USING (true); CREATE POLICY "incoming_inspections_manage_quality" ON public.incoming_inspections FOR ALL TO authenticated USING (public.phase6_can_quality(auth.uid())) WITH CHECK (public.phase6_can_quality(auth.uid()));
CREATE TABLE IF NOT EXISTS public.supplier_ncrs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ncr_number text NOT NULL UNIQUE, vendor_id uuid NOT NULL REFERENCES public.vendors(id), grn_id uuid REFERENCES public.goods_receipt_notes(id), inspection_id uuid REFERENCES public.incoming_inspections(id), status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','RESPONSE_DUE','CONTAINMENT','VERIFICATION','CLOSED')), issue_summary text NOT NULL, root_cause text, corrective_action text, response_due_date date, verified_by uuid, verified_at timestamptz, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.supplier_ncrs TO authenticated; GRANT ALL ON public.supplier_ncrs TO service_role; ALTER TABLE public.supplier_ncrs ENABLE ROW LEVEL SECURITY; CREATE POLICY "supplier_ncrs_read_internal" ON public.supplier_ncrs FOR SELECT TO authenticated USING (true); CREATE POLICY "supplier_ncrs_manage_quality" ON public.supplier_ncrs FOR ALL TO authenticated USING (public.phase6_can_quality(auth.uid())) WITH CHECK (public.phase6_can_quality(auth.uid()));
CREATE TABLE IF NOT EXISTS public.rtv_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id uuid NOT NULL REFERENCES public.vendors(id), grn_id uuid REFERENCES public.goods_receipt_notes(id), ncr_id uuid REFERENCES public.supplier_ncrs(id), rtv_number text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','AUTHORIZED','DISPATCHED','CLOSED')), reason text, courier text, awb_number text, dispatched_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.rtv_records TO authenticated; GRANT ALL ON public.rtv_records TO service_role; ALTER TABLE public.rtv_records ENABLE ROW LEVEL SECURITY; CREATE POLICY "rtv_records_read_internal" ON public.rtv_records FOR SELECT TO authenticated USING (true); CREATE POLICY "rtv_records_manage_purchase_quality" ON public.rtv_records FOR ALL TO authenticated USING (public.can_purchase(auth.uid()) OR public.phase6_can_quality(auth.uid())) WITH CHECK (public.can_purchase(auth.uid()) OR public.phase6_can_quality(auth.uid()));
CREATE TABLE IF NOT EXISTS public.quick_expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), expense_number text NOT NULL UNIQUE, requester_id uuid NOT NULL DEFAULT auth.uid(), project_id uuid REFERENCES public.projects(id), department_id uuid REFERENCES public.departments(id), category text NOT NULL, description text NOT NULL, amount numeric NOT NULL CHECK (amount > 0), currency text NOT NULL DEFAULT 'INR', receipt_path text, status text NOT NULL DEFAULT 'SUBMITTED' CHECK (status IN ('SUBMITTED','FINANCE_REVIEW','APPROVED','REJECTED','PAID')), is_rd boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.quick_expenses TO authenticated; GRANT ALL ON public.quick_expenses TO service_role; ALTER TABLE public.quick_expenses ENABLE ROW LEVEL SECURITY; CREATE POLICY "quick_expenses_read_owner_finance" ON public.quick_expenses FOR SELECT TO authenticated USING (requester_id = auth.uid() OR public.phase6_can_finance(auth.uid())); CREATE POLICY "quick_expenses_create_owner" ON public.quick_expenses FOR INSERT TO authenticated WITH CHECK (requester_id = auth.uid()); CREATE POLICY "quick_expenses_update_owner_or_finance" ON public.quick_expenses FOR UPDATE TO authenticated USING (requester_id = auth.uid() OR public.phase6_can_finance(auth.uid())) WITH CHECK (requester_id = auth.uid() OR public.phase6_can_finance(auth.uid()));
CREATE TABLE IF NOT EXISTS public.payment_milestones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), po_id uuid REFERENCES public.purchase_orders(id), project_id uuid REFERENCES public.projects(id), vendor_id uuid REFERENCES public.vendors(id), milestone_type text NOT NULL CHECK (milestone_type IN ('ADVANCE','DELIVERY','GRN_ACCEPTANCE','INVOICE','CUSTOM')), basis text NOT NULL DEFAULT 'BASIC' CHECK (basis IN ('BASIC','TOTAL','FIXED')), percentage numeric, amount numeric NOT NULL CHECK (amount >= 0), currency text NOT NULL DEFAULT 'INR', trigger_date date, due_date date, status text NOT NULL DEFAULT 'PLANNED' CHECK (status IN ('PLANNED','PENDING_APPROVAL','APPROVED','BLOCKED','PAID','CANCELLED')), notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.payment_milestones TO authenticated; GRANT ALL ON public.payment_milestones TO service_role; ALTER TABLE public.payment_milestones ENABLE ROW LEVEL SECURITY; CREATE POLICY "payment_milestones_read_finance_purchase" ON public.payment_milestones FOR SELECT TO authenticated USING (public.phase6_can_finance(auth.uid()) OR public.can_purchase(auth.uid())); CREATE POLICY "payment_milestones_manage_finance" ON public.payment_milestones FOR ALL TO authenticated USING (public.phase6_can_finance(auth.uid())) WITH CHECK (public.phase6_can_finance(auth.uid()));
CREATE INDEX IF NOT EXISTS purchase_requests_project_status_idx ON public.purchase_requests(project_id, status); CREATE INDEX IF NOT EXISTS purchase_request_items_component_idx ON public.purchase_request_items(component_id); CREATE INDEX IF NOT EXISTS inventory_lots_component_status_idx ON public.inventory_lots(component_id, quality_status, created_at); CREATE INDEX IF NOT EXISTS incoming_inspections_status_idx ON public.incoming_inspections(status); CREATE INDEX IF NOT EXISTS payment_milestones_status_due_idx ON public.payment_milestones(status, due_date);
CREATE OR REPLACE FUNCTION public.phase6_shortage_snapshot(_bom_id uuid) RETURNS TABLE(bom_item_id uuid, component_id uuid, mpn text, required_quantity numeric, on_hand numeric, reserved numeric, quality_hold numeric, open_po numeric, available numeric, shortage numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ WITH bom AS (SELECT i.id, i.matched_component_id, i.mpn, i.quantity::numeric AS required_quantity FROM public.project_bom_items i WHERE i.bom_id = _bom_id), stock AS (SELECT l.component_id, COALESCE(sum(l.quantity),0)::numeric AS on_hand FROM public.locations l GROUP BY l.component_id), reserved AS (SELECT r.component_id, COALESCE(sum(r.quantity),0)::numeric AS reserved FROM public.inventory_reservations r WHERE r.status = 'ACTIVE' GROUP BY r.component_id), hold AS (SELECT il.component_id, COALESCE(sum(il.quantity_available),0)::numeric AS quality_hold FROM public.inventory_lots il WHERE il.quality_status <> 'AVAILABLE' GROUP BY il.component_id), openpo AS (SELECT poi.component_id, COALESCE(sum(GREATEST(poi.quantity_ordered - poi.quantity_received - poi.quantity_rejected,0)),0)::numeric AS open_po FROM public.purchase_order_items poi JOIN public.purchase_orders po ON po.id=poi.po_id WHERE po.status IN ('DRAFT','SENT','PARTIALLY_RECEIVED') GROUP BY poi.component_id) SELECT b.id, b.matched_component_id, b.mpn, b.required_quantity, COALESCE(s.on_hand,0), COALESCE(r.reserved,0), COALESCE(h.quality_hold,0), COALESCE(o.open_po,0), GREATEST(COALESCE(s.on_hand,0)-COALESCE(r.reserved,0)-COALESCE(h.quality_hold,0),0), GREATEST(b.required_quantity-GREATEST(COALESCE(s.on_hand,0)-COALESCE(r.reserved,0)-COALESCE(h.quality_hold,0),0)-COALESCE(o.open_po,0),0) FROM bom b LEFT JOIN stock s ON s.component_id=b.matched_component_id LEFT JOIN reserved r ON r.component_id=b.matched_component_id LEFT JOIN hold h ON h.component_id=b.matched_component_id LEFT JOIN openpo o ON o.component_id=b.matched_component_id; $$;
CREATE OR REPLACE FUNCTION public.create_purchase_request_from_bom_shortage(_bom_id uuid, _required_date date DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_pr_id uuid; v_project_id uuid; v_department_id uuid; v_number text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; SELECT b.project_id INTO v_project_id FROM public.project_boms b WHERE b.id = _bom_id; IF v_project_id IS NULL THEN RAISE EXCEPTION 'BOM not found'; END IF; SELECT id INTO v_department_id FROM public.departments WHERE code IN ('PUR','PD') AND is_active ORDER BY CASE code WHEN 'PUR' THEN 0 ELSE 1 END LIMIT 1; v_number := public.next_business_number('purchase_request'); INSERT INTO public.purchase_requests(request_number, source_type, source_entity_id, project_id, bom_id, department_id, requester_id, status, required_date, notes) VALUES (v_number,'BOM_SHORTAGE',_bom_id,v_project_id,_bom_id,v_department_id,auth.uid(),'DRAFT',_required_date,'Generated from BOM shortage snapshot') RETURNING id INTO v_pr_id; INSERT INTO public.purchase_request_items(purchase_request_id,component_id,mpn,required_quantity,shortage_quantity) SELECT v_pr_id, component_id, mpn, required_quantity, shortage FROM public.phase6_shortage_snapshot(_bom_id) WHERE shortage > 0; IF NOT EXISTS (SELECT 1 FROM public.purchase_request_items WHERE purchase_request_id=v_pr_id) THEN RAISE EXCEPTION 'No purchase shortage found for BOM'; END IF; RETURN v_pr_id; END; $$;
CREATE OR REPLACE FUNCTION public.phase6_touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['purchase_requests','rfqs','quotations','po_shipments','inventory_lots','inventory_reservations','incoming_inspections','supplier_ncrs','rtv_records','quick_expenses','payment_milestones'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', t || '_touch_updated_at', t); EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.phase6_touch_updated_at()', t || '_touch_updated_at', t); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.phase6_shortage_snapshot(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.phase6_shortage_snapshot(uuid) TO authenticated, service_role; REVOKE ALL ON FUNCTION public.create_purchase_request_from_bom_shortage(uuid,date) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_purchase_request_from_bom_shortage(uuid,date) TO authenticated, service_role;